// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/**
 * @title ITradingSafeFactory
 * @author ether.fi
 * @notice Mainnet TradingSafe factory surface consumed by the TopUp redirect flow and
 *         token-support checks.
 * @dev Implementation lives in the TradingSafe project (COR-728). Defined here so that
 *      consumers can resolve `sourceSafe → tradingSafe` without taking a hard dependency
 *      on the full factory interface.
 */
interface ITradingSafeFactory {
    /**
     * @notice Returns the deterministic TradingSafe address for a given source-chain safe.
     * @param sourceSafe Source-chain safe address.
     * @return The pre-computed destination TradingSafe address (may not yet have code).
     */
    function getDeterministicAddress(address sourceSafe) external view returns (address);

    /**
     * @notice Returns whether `safeAddr` is a TradingSafe deployed by this factory.
     * @dev Used by drain-style contracts to enforce that funds can only be routed to a
     *      registered TradingSafe, never to an arbitrary recipient.
     * @param safeAddr The address to check.
     * @return True if the address was deployed by this factory.
     */
    function isEtherFiSafe(address safeAddr) external view returns (bool);

    /**
     * @notice Returns the TopUp address a deployed TradingSafe settles to, recorded at
     *         deploy time (the identity the safe was derived from).
     * @dev Reverts for addresses this factory didn't deploy — callers get a guaranteed
     *      non-zero, deploy-time-bound destination for any registered TradingSafe.
     * @param tradingSafe The TradingSafe to look up.
     */
    function getTopUpAddress(address tradingSafe) external view returns (address);

    /**
     * @notice Returns whether `token` is a supported trading asset.
     * @dev Delegates to the configured TradingLens registry. Used by the TopUp source
     *      factory to gate `redirectToTradingSafe` to trading-supported tokens only.
     * @param token The token to check.
     * @return True if `token` is supported for trading.
     */
    function isSupportedToken(address token) external view returns (bool);
}

